<div class="page-title"><div><em>HELP CENTER</em><h1><?=html_escape($ticket['subject'])?></h1><p><?=$ticket['reference']?> · <?=date('M j, Y',strtotime($ticket['created_at']))?> · <?=ucwords(str_replace('_',' ',$ticket['status']))?></p></div><a class="outline" href="<?=site_url('support')?>">← All requests</a></div><section class="panel conversation"><?php foreach($ticket['messages'] as $m):?><div class="message <?=$m['is_staff']?'staff':''?>"><header><b><?=html_escape($m['first_name'].' '.$m['last_name'])?></b><small><?=date('M j, g:i a',strtotime($m['created_at']))?><?=$m['is_staff']?' · NorthWest support':''?></small></header><p><?=nl2br(html_escape($m['message']))?></p></div><?php endforeach?></section><?php if(in_array($ticket['status'],array('open','in_progress'),TRUE)):?><section class="panel reply-form"><h2>Add a reply</h2><?=form_open('support/'.$ticket['id'])?><textarea name="message" rows="4" required placeholder="Type your message…"></textarea><button class="btn">Send reply ›</button></form></section><?php else:?><div class="empty">This request is <?=html_escape($ticket['status'])?>. If you need further help, please start a new request.</div><?php endif?>
